import{_ as o}from"./chunks/ai-diagnosis.CeD7Zjye.js";import{_ as s,C as i,o as n,c as r,ak as t,E as d}from"./chunks/framework.sV-XtlWr.js";const l="/diagrams/failure-clustering-semantic-merge.svg",w=JSON.parse('{"title":"AI diagnosis","description":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default.","frontmatter":{"title":"AI diagnosis","description":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/ai-diagnosis.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/ai-diagnosis.html"}],["meta",{"property":"og:title","content":"AI diagnosis | Piwi Dashboard"}],["meta",{"property":"og:description","content":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default."}]]},"headers":[],"relativePath":"features/ai-diagnosis.md","filePath":"features/ai-diagnosis.md","lastUpdated":1791061436000}'),c={name:"features/ai-diagnosis.md"};function h(g,e,u,p,m,f){const a=i("DemoExamples");return n(),r("div",null,[e[0]||(e[0]=t('<h1 id="ai-diagnosis" tabindex="-1">AI diagnosis <a class="header-anchor" href="#ai-diagnosis" aria-label="Permalink to &quot;AI diagnosis&quot;">​</a></h1><p>When a run finishes, Piwi groups related failures into <a href="./failure-clusters.html">failure clusters</a> and, optionally, asks an LLM to explain them. Clustering decides <em>what</em> to diagnose; AI diagnosis explains <em>why</em> it broke, against the code that changed.</p><h2 id="semantic-merging-optional" tabindex="-1">Semantic merging (optional) <a class="header-anchor" href="#semantic-merging-optional" aria-label="Permalink to &quot;Semantic merging (optional)&quot;">​</a></h2><p>If an <strong>embedding</strong> model role is configured (Settings → AI), Piwi adds a semantic layer on top of the deterministic fingerprint. After a run, the clusters first seen in it are embedded and compared (cosine similarity) against the project&#39;s other open clusters; near-duplicates above <code>PIWI_CLUSTER_SIMILARITY_THRESHOLD</code> (default <code>0.92</code>) are merged into the longest-lived cluster, and a fingerprint alias sends future occurrences to the survivor. This catches one root cause phrased differently enough to dodge the fingerprint. The text is cleaned before embedding (ANSI codes, framework stack frames and volatile tokens removed), and older clusters without a vector are embedded a few at a time over the runs that follow.</p><p>Pairs in the <strong>ambiguous band</strong>, between <code>PIWI_CLUSTER_SUGGEST_THRESHOLD</code> (default <code>0.80</code>) and the merge threshold, are not merged automatically. When AI is configured, a model judges the pair from its error text, locators, most-affected tests and overlap: it merges on a confident yes, turns a less confident yes into a <strong>merge suggestion</strong> on the project&#39;s Failure clusters tab, for a reporter or admin to approve or dismiss, and leaves a no apart. Without AI, or past five model calls in a run, the pair becomes a suggestion directly. This runs after every finished run whenever an embedding role is configured, independently of auto-diagnose.</p><p>Each pair is judged once: the model&#39;s no is kept, so the same pair is not sent to the model again. A pair that someone dismissed, or that came from <a href="#split-a-cluster-by-hand">moving tests to a new cluster</a>, is never merged automatically, however close the two clusters score.</p><figure><img src="'+l+'" alt="Diagram of the semantic merging flow: clusters are embedded, compared by cosine similarity, and kept apart, adjudicated by a model, or merged depending on the score"><figcaption>The cosine score decides between keeping two clusters apart, asking a model (or a person), and merging them.</figcaption></figure><p>With auto-diagnose on, new clusters also get a short <strong>title</strong> from one cheap batched model call per run. Without one, a cluster is named from its error kind, locator, route and spec file, such as <code>Timeout on getByLabel(&#39;Email address&#39;) in checkout.spec.ts</code>.</p><h3 id="split-a-cluster-by-hand" tabindex="-1">Split a cluster by hand <a class="header-anchor" href="#split-a-cluster-by-hand" aria-label="Permalink to &quot;Split a cluster by hand&quot;">​</a></h3><p>The opposite of a merge needs no AI. When some of a cluster&#39;s tests fail with the same error for a different reason, select them in the cluster page&#39;s <strong>Affected tests</strong> and choose <strong>Move to a new cluster</strong> (reporter or administrator). Their failures move to a new cluster at once, with the triage note you type, and the cluster they left gains a line naming the move. Later failures of those tests with the same error join the new cluster, the other tests&#39; failures stay where they were, and the two clusters are never merged automatically.</p><h2 id="enabling-ai-diagnosis" tabindex="-1">Enabling AI diagnosis <a class="header-anchor" href="#enabling-ai-diagnosis" aria-label="Permalink to &quot;Enabling AI diagnosis&quot;">​</a></h2><p>AI diagnosis needs an <a href="/guide/ai-provider.html">AI provider</a>: the providers, model roles, streaming and automatic diagnosis of new clusters are set up there.</p><h2 id="response-language" tabindex="-1">Response language <a class="header-anchor" href="#response-language" aria-label="Permalink to &quot;Response language&quot;">​</a></h2><p>A diagnosis comes back in the <a href="/guide/ai-provider.html#response-language">response language</a> set for the instance or the project.</p><h2 id="what-a-diagnosis-contains" tabindex="-1">What a diagnosis contains <a class="header-anchor" href="#what-a-diagnosis-contains" aria-label="Permalink to &quot;What a diagnosis contains&quot;">​</a></h2><p>A diagnosis is grounded in your actual run, not a generic &quot;ask AI&quot; button. Each result includes:</p><ul><li><strong>Category</strong> and <strong>confidence</strong></li><li><strong>Root cause</strong>: the most likely explanation</li><li><strong>Evidence</strong>: the signals the model relied on, each citing a section of the page</li><li><strong>Suggested fix</strong> and <strong>prevention tips</strong></li></ul><figure><img src="'+o+'" alt="The AI diagnosis in the toolbox of a failure cluster page"><figcaption>The AI diagnosis in a cluster page&#39;s toolbox: category, confidence, root cause, evidence and a suggested fix.</figcaption></figure><h2 id="diagnosing-one-execution" tabindex="-1">Diagnosing one execution <a class="header-anchor" href="#diagnosing-one-execution" aria-label="Permalink to &quot;Diagnosing one execution&quot;">​</a></h2><p>A cluster page diagnoses every failure that shares a fingerprint. On a single failing <a href="./evidence.html#one-execution-diagnosis-first">execution</a>, the <strong>Diagnosis</strong> section of <strong>More ways to fix</strong> shows the cluster&#39;s completed diagnosis with an <strong>Open</strong> link to it; without one, it diagnoses just that execution, with the same panel and model: handy when a failure has not clustered yet. Execution and cluster diagnoses are stored separately, and running one never overwrites the other.</p><p>A stored diagnosis stays on screen even with no provider configured. With no result and no provider, <strong>Copy prompt</strong> copies the exact request the model would receive, trimmed to the <a href="/guide/ai-provider.html#context-limits-and-token-cost">context limits</a>, so you can paste it into your own AI tool.</p><h2 id="scm-grounded-context" tabindex="-1">SCM-grounded context <a class="header-anchor" href="#scm-grounded-context" aria-label="Permalink to &quot;SCM-grounded context&quot;">​</a></h2><p>The diagnosis is fed the code that changed. On a cluster page you can:</p><ul><li><strong>Pin a baseline commit</strong>: the diagnosis includes the diff between that commit and the run.</li><li><strong>Browse and cherry-pick commits</strong>: add the full diff of specific commits.</li><li><strong>Preview the exact context</strong> before running it, so nothing leaves your server by surprise.</li></ul><p>Without a pinned baseline, the diff starts at the last green run before the cluster first appeared, else at the last run where this test passed; the context preview names which one it used. With the repository reachable, Piwi also sends the <strong>full current content</strong> of the most suspect changed files and of the failing test&#39;s local imports (page objects, helpers, fixtures), capped by <code>PIWI_AI_MAX_SOURCE_FILES</code> (default 4) and <code>PIWI_AI_MAX_SOURCE_FILE_CHARS</code>. The repository connection is set up on <a href="/guide/source-control.html">Source control</a>.</p><h3 id="validated-patches" tabindex="-1">Validated patches <a class="header-anchor" href="#validated-patches" aria-label="Permalink to &quot;Validated patches&quot;">​</a></h3><p>Every suggested patch is checked before it reaches you, by dry-running each hunk against the source files the model was shown. The patch carries one badge: <strong>Applies cleanly</strong>, <strong>Applies with offset</strong> (<code>git apply</code> should still succeed), <strong>Does not apply</strong> (the file diverged), <strong>Invalid diff</strong>, or <strong>Unverified</strong> (the file was not in the context). The model is told to return no patch unless it can quote the lines it changes. Applying a patch is always manual: <strong>Copy</strong>, <strong>Copy <code>git apply</code> command</strong> or <strong>Download <code>.patch</code></strong>. Only <a href="./auto-heal.html">auto-heal</a> writes to your repository, with deterministic locator edits rather than model output.</p><h2 id="diagnoses-written-by-an-agent" tabindex="-1">Diagnoses written by an agent <a class="header-anchor" href="#diagnoses-written-by-an-agent" aria-label="Permalink to &quot;Diagnoses written by an agent&quot;">​</a></h2><p>A coding agent can record its own diagnosis on a cluster with the MCP tool <code>record_diagnosis</code>, in the same JSON a model returns here. It needs no AI provider on this instance, its patch is validated against the source the cluster failed at when <a href="/guide/source-control.html">source control</a> is connected, and the panel shows it as <strong>written by an agent</strong> with the model it named. It replaces the current diagnosis, which stays in the history. Declining the <strong>Agent diagnoses</strong> capability refuses them; declining AI diagnosis does not.</p><h2 id="locator-healing" tabindex="-1">Locator healing <a class="header-anchor" href="#locator-healing" aria-label="Permalink to &quot;Locator healing&quot;">​</a></h2><p>When the failure is a broken locator, the context includes the ranked replacements and the recommended fix from <a href="./locator-healing.html">Locator healing</a>, and the model is told to use that fix rather than invent a locator.</p><h2 id="fix-plans" tabindex="-1">Fix plans <a class="header-anchor" href="#fix-plans" aria-label="Permalink to &quot;Fix plans&quot;">​</a></h2><p>The diagnosis, its patch, the locator fix and the verify command come together in a fix plan: see <a href="./fix-plans.html">Fix plans, reproduce &amp; bisect</a>.</p><h2 id="diagnosis-history" tabindex="-1">Diagnosis history <a class="header-anchor" href="#diagnosis-history" aria-label="Permalink to &quot;Diagnosis history&quot;">​</a></h2><p>Every re-diagnose keeps the previous result; a nightly sweep keeps the newest 20 per cluster (<code>PIWI_RETENTION_DIAGNOSIS_VERSIONS</code>, <code>0</code> keeps all). <strong>History</strong> in the panel header lists them newest first, with the model, category, confidence and token cost, and shows what changed since each one.</p><p>A re-diagnose sends the previous assessment to the model: its category, confidence, summary and root cause, the cluster&#39;s triage note, and, when you rated it unhelpful, your note and an instruction not to repeat it without new evidence. A rating belongs to the version it rated: the new diagnosis starts unrated, and the history keeps the old one&#39;s thumbs.</p><p>A diagnosis is flagged <strong>may be stale</strong> only when the evidence changed since it ran <strong>and</strong> the cluster is still failing; the banner says whether new occurrences or new evidence caused it.</p><h2 id="custom-instructions" tabindex="-1">Custom instructions <a class="header-anchor" href="#custom-instructions" aria-label="Permalink to &quot;Custom instructions&quot;">​</a></h2><p>Tailor the analysis to your stack with <strong>global</strong> instructions (Settings → AI) and <strong>per-project</strong> instructions (Project → Settings → AI diagnosis). Use them to describe your architecture, common false positives, or house style for fixes.</p><h2 id="context-limits-and-token-cost" tabindex="-1">Context limits (and token cost) <a class="header-anchor" href="#context-limits-and-token-cost" aria-label="Permalink to &quot;Context limits (and token cost)&quot;">​</a></h2><p>Each input sent to the model is capped to keep diagnoses fast and affordable; the caps are set on the <a href="/guide/ai-provider.html#context-limits-and-token-cost">AI provider</a> page.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>API keys are encrypted at rest with <a href="/reference/configuration.html#general"><code>PIWI_SECRET_KEY</code></a>. When you run a diagnosis, the bounded context above is sent to your configured provider, so for fully local analysis, use Ollama or another self-hosted OpenAI-compatible model and keep everything on your own infrastructure.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> needs no AI provider: some clusters carry a completed diagnosis with a validated patch, and the others run a simulated streaming diagnosis.</p>',45)),d(a),e[1]||(e[1]=t('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: clusters first, then a diagnosis for the few causes left</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a>: how failures are grouped, and whether the fix worked</li><li><a href="/guide/privacy.html">Privacy &amp; data flow</a>: exactly what a diagnosis sends, and where</li><li><a href="./notifications.html">Notifications &amp; alerts</a>: <code>diagnosis.completed</code>, <code>cluster.new</code>, <code>cluster.fixed</code> and <code>cluster.regressed</code></li><li><a href="/features/mcp.html">MCP server</a>: let AI agents query clusters and diagnoses directly</li></ul>',2))])}const v=s(c,[["render",h]]);export{w as __pageData,v as default};
